import { captureScreenshot } from "./plugins/index";

export default function () {
  // Use Cypress's built-in `cy.screenshot` command to capture screenshots
  // and save them to the specified folder
  Cypress.Commands.add("screenshot", (options) => {
    const defaultOptions = {
      capture: "fullPage",
      overlay: false,
      clip: null,
      filename: Cypress.now().toString(),
    };
    const allOptions = { ...defaultOptions, ...options };
    return cy.wrap().then(() => {
      return cy.task("capture:screenshot", allOptions).then((result) => {
        const { image, url } = result;
        const fileName = Cypress.config("screenshotsFolder") + `/${options.filename}.png`;
        cy.writeFile(fileName, image);
        return url;
      });
    });
  });

  // Use Cypress's built-in `cy.matchImageSnapshot` command to compare
  // screenshots against a baseline image
  Cypress.Commands.add("matchImageSnapshot", (options) => {
    options.customDiffConfig = {
      threshold: 0.01, // Set custom threshold for image comparison
    };
    return cy.matchImageSnapshot(options);
  });

  // Custom task to capture a screenshot and return the file path
  Cypress.Commands.add("capture:screenshot", (options) => {
    return new Cypress.Promise((resolve, reject) => {
      captureScreenshot(options, (error, result) => {
        if (error) {
          return reject(error);
        }
        resolve(result);
      });
    });
  });
}
